import{_ as i,C as n,o as r,c as a,j as t,a as s,E as d,a6 as h}from"./chunks/framework.CCKCzdWs.js";const f=JSON.parse('{"title":"Piwi Picker and your editor","description":"How Piwi Picker pairs with the VS Code and JetBrains windows on your machine for Send to editor and the Runs window: Pair and a code to allow, the pairing panel, the proof asked before any token goes, and what it says when one does not answer.","frontmatter":{"title":"Piwi Picker and your editor","description":"How Piwi Picker pairs with the VS Code and JetBrains windows on your machine for Send to editor and the Runs window: Pair and a code to allow, the pairing panel, the proof asked before any token goes, and what it says when one does not answer.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/editor-pairing.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/editor-pairing.html"}],["meta",{"property":"og:title","content":"Piwi Picker and your editor | Piwi for Playwright"}],["meta",{"property":"og:description","content":"How Piwi Picker pairs with the VS Code and JetBrains windows on your machine for Send to editor and the Runs window: Pair and a code to allow, the pairing panel, the proof asked before any token goes, and what it says when one does not answer."}]]},"headers":[],"relativePath":"features/editor-pairing.md","filePath":"features/editor-pairing.md","lastUpdated":1795554528000}'),w={name:"features/editor-pairing.md"};function p(l,e,c,g,u,k){const o=n("Needs");return r(),a("div",null,[e[0]||(e[0]=t("h1",{id:"piwi-picker-and-your-editor",tabindex:"-1"},[s("Piwi Picker and your editor "),t("a",{class:"header-anchor",href:"#piwi-picker-and-your-editor","aria-label":'Permalink to "Piwi Picker and your editor"'},"​")],-1)),d(o,{extension:"",editor:""}),e[1]||(e[1]=h('<p><a href="./editor-recording.html#send-from-piwi-picker">Send to editor</a> and the <a href="./runs-window.html">Runs window</a> reach your editor through one pairing. The desktop app has a pairing of its own, which the Runs window follows beside it (<a href="./runs-window.html#the-desktop-app-s-runs">the desktop app&#39;s runs</a>).</p><h2 id="pair" tabindex="-1">Pair <a class="header-anchor" href="#pair" aria-label="Permalink to &quot;Pair&quot;">​</a></h2><ol><li>In Piwi Picker&#39;s settings, under <strong>Editor</strong>, click Piwi Picker&#39;s <strong>Pair</strong>. It asks the ports the editors of this computer listen on which editor answers there, VS Code on 7247 to 7251 and a JetBrains IDE&#39;s built-in server on 63342 to 63361, and lists them when it finds more than one. The browser asks once for access to <code>127.0.0.1</code>; Piwi Picker gives back the ports it did not pair with.</li><li>Piwi Picker shows a code, and the editor shows the request: Piwi Picker in your browser asks to pair. Click <strong>Type the code…</strong> in the editor&#39;s notification or in its pairing panel and type the code Piwi Picker shows; deny a request you did not make. The editor hands over the pairing&#39;s token with a proof of the code typed, and Piwi Picker keeps it only when the proof is of its own code: a program that answers on an editor&#39;s port never sees the code, so it cannot pair itself.</li></ol><p><strong>Piwi: Pair with Piwi Picker</strong> (<strong>Tools → Piwi → Pair with Piwi Picker</strong> in a JetBrains IDE, also in the status bar item&#39;s menu) opens the pairing panel. A request nobody answers expires after five minutes; a new Pair takes the place of the one before, an extension denied waits a minute before it asks again, and an editor holds three at once at most. VS Code windows listen where Piwi Picker looks once Piwi starts; a second window of the same editor leaves the port to the first.</p><p>Without a code, the editor&#39;s <strong>Piwi: Copy the pairing address for Piwi Picker</strong> copies <code>http://127.0.0.1:&lt;port&gt;/…#&lt;token&gt;</code>, which Piwi Picker&#39;s <strong>Pair with an address</strong> takes. That is the way for a remote window, which Piwi Picker does not find on its own: <a href="/guide/remote-development.html">Remote development</a>.</p><p>Every test run Piwi starts gets the pairing address and token as <code>PIWI_EDITOR_SEND</code>, so a locator picked at one of its stops reaches the editor: such a run starts the listener and creates the token if there is none. The capture fixtures hide it from the processes a test starts; the Playwright runner and its <code>webServer</code> still have it, and programs running as your user are not kept out.</p><h2 id="the-pairing-panel" tabindex="-1">The pairing panel <a class="header-anchor" href="#the-pairing-panel" aria-label="Permalink to &quot;The pairing panel&quot;">​</a></h2><p>The editor shows the pairing in a panel of its own: the <strong>Piwi Picker</strong> view of the Piwi panel in VS Code, the <strong>Piwi Picker</strong> tab of the Piwi tool window in a JetBrains IDE. It lists a request that waits, with <strong>Type the code…</strong> and <strong>Deny</strong>; once paired, the browser it is paired with and since when, when Piwi Picker was last heard from (it asks for the runs while its Runs window is open), and the port it reaches the editor on. Not paired, it says how to pair.</p><p><strong>Unpair</strong> there (<strong>Piwi: Unpair Piwi Picker</strong>) gives the editor a new token, after asking: Piwi Picker, and any run started before, reach it again only once paired again. Each JetBrains IDE keeps a token of its own, so Unpair in one leaves the others paired. The connections to the runs Piwi Picker holds already last until the editor service restarts. In VS Code, a window that kept the port of an earlier pairing outside 7247 to 7251 moves to one of them.</p><h2 id="what-the-pairing-reaches" tabindex="-1">What the pairing reaches <a class="header-anchor" href="#what-the-pairing-reaches" aria-label="Permalink to &quot;What the pairing reaches&quot;">​</a></h2><p>The editor listens on the loopback interface only, answers only a request addressed to <code>127.0.0.1</code> or <code>localhost</code> at its port, and accepts one only with the token. Before Piwi Picker sends the token, the editor proves it holds it, so another program that took the port is sent nothing; the settings ask for that proof as they open and after <strong>Pair</strong>. With several VS Code windows open, the one holding the paired port receives; when it closes, another open window takes the port within seconds, unless every other one already listens on a port of its own for a run it started meanwhile.</p><p>Piwi Picker&#39;s background worker reaches the editor&#39;s services on <code>127.0.0.1</code> only once the paired port proves it holds the pairing&#39;s token (<a href="./editor-run-control.html#how-it-works">how the pieces connect</a>), as the desktop app proves it holds its own. The Runs window talks to that worker alone, and makes no network call of its own. An older editor extension gives the image and the controls alone.</p><h2 id="windows-that-open-and-close" tabindex="-1">Windows that open and close <a class="header-anchor" href="#windows-that-open-and-close" aria-label="Permalink to &quot;Windows that open and close&quot;">​</a></h2><p>An editor window you open later shows in the Runs window within seconds: each window&#39;s service names the others, without their tokens, and the worker asks the paired editor for them. While the Runs window is open, it also asks every minute. A run whose window stops answering stays listed, grayed and as last heard, until that window answers again, ten minutes at most, and a stop&#39;s <strong>Watch</strong> starts again then.</p><h2 id="when-the-editor-does-not-answer" tabindex="-1">When the editor does not answer <a class="header-anchor" href="#when-the-editor-does-not-answer" aria-label="Permalink to &quot;When the editor does not answer&quot;">​</a></h2><p>A line under the Runs window&#39;s title says how each paired tool stands, a broken pairing included, with <strong>Look again</strong> or <strong>Open the settings</strong> where its sentence needs them. When the paired port answers without proving it holds the token, the worker asks a few times more, then once a minute while the Runs window is open: click Piwi Picker&#39;s <strong>Pair</strong> again if the editor moved to another port. One that answers with no proof and no such page is not your editor&#39;s Piwi extension. While no window of a paired tool answers, the popup&#39;s <strong>Runs</strong> tile stays, muted, and the Runs window says why.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./runs-window.html">Runs window</a>: the runs it follows, and their controls.</li><li><a href="./editor-recording.html#send-from-piwi-picker">Record tests from the editor</a>: what Send to editor inserts.</li><li><a href="/guide/remote-development.html">Remote development</a>: the pairing address of a remote window.</li><li><a href="./extension.html">Browser extension</a>: Piwi Picker&#39;s other tools, and its permissions.</li></ul>',18))])}const m=i(w,[["render",p]]);export{f as __pageData,m as default};
